import React, { useId, useState } from 'react';
import { Link } from 'react-router-dom';
import client from './client';
import { ConfirmDialog } from './Dialog';
import NameDialog from './FormDialog';
import { SERVICES, serviceName } from './services';
import { Card, RowMenu } from './Console';
import { FiArrowUpRight } from 'react-icons/fi';

const MAX_PROJECTS = 20;

// Each project is one row: its name, its services (the name opens the product, the switch turns it on or off)
// and a menu for rename and delete. Turning a service on is one step; turning it off asks first because it revokes access.
export default function ProjectsSection({ workspace, canManage, run }) {
  const [dialog, setDialog] = useState(null);
  const headingId = useId();
  const atLimit = workspace.projects.length >= MAX_PROJECTS;

  const close = () => setDialog(null);
  const toggleService = async (project, service, on) => {
    if (on) {
      const result = await run((revision) => client.enableService(workspace.id, project.id, service, revision), { success: `${serviceName(service)} is on for ${project.name}.` });
      return result;
    }
    setDialog({ type: 'disable', project, service });
    return { ok: true };
  };

  return (
    <Card
      title={<>Projects{workspace.projects.length > 0 && <small>{workspace.projects.length}</small>}</>}
      headingId={headingId}
      action={canManage && (
        <button type="button" className="cs-action" onClick={() => setDialog({ type: 'create' })} disabled={atLimit} aria-describedby={atLimit ? `${headingId}-limit` : undefined}>New project</button>
      )}
    >
      {atLimit && <p id={`${headingId}-limit`} className="cs-note">This workspace has reached its limit of {MAX_PROJECTS} projects.</p>}

      {workspace.projects.length === 0 ? (
        <p className="cs-note" data-state="empty">{canManage ? 'No projects yet. Create one, then switch on Stream or RMS for it.' : 'No projects yet. An owner or admin can create the first one.'}</p>
      ) : (
        <ul className="cs-list">
          {workspace.projects.map((project) => (
            <ProjectRow
              key={project.id}
              project={project}
              workspaceId={workspace.id}
              canManage={canManage}
              onService={toggleService}
              onRename={() => setDialog({ type: 'rename', project })}
              onDelete={() => setDialog({ type: 'delete', project })}
            />
          ))}
        </ul>
      )}

      {dialog?.type === 'create' && (
        <NameDialog
          title="New project"
          label="Project name"
          hint="Up to 64 characters."
          submitLabel="Create project"
          busyLabel="Creating…"
          onClose={close}
          onSubmit={(name, extra) => run(
            (revision) => client.createProject(workspace.id, name, SERVICES.map((s) => s.id).filter((id) => extra.services?.[id]), revision),
            { success: `Created ${name}.` },
          )}
        >
          {({ extra, setExtra, busy }) => (
            <fieldset className="ws-fieldset" disabled={busy}>
              <legend>Turn on now (optional)</legend>
              {SERVICES.map((service) => (
                <label key={service.id} className="ws-check">
                  <input
                    type="checkbox"
                    checked={Boolean(extra.services?.[service.id])}
                    onChange={(event) => setExtra({ ...extra, services: { ...extra.services, [service.id]: event.target.checked } })}
                  />
                  <span><strong>{service.name}</strong><span>{service.description}</span></span>
                </label>
              ))}
              <p className="ws-hint">You can change this later.</p>
            </fieldset>
          )}
        </NameDialog>
      )}

      {dialog?.type === 'rename' && (
        <NameDialog
          title="Rename project"
          label="Project name"
          initial={dialog.project.name}
          submitLabel="Save name"
          onClose={close}
          onSubmit={(name) => run((revision) => client.renameProject(workspace.id, dialog.project.id, name, revision), { success: 'Project renamed.' })}
        />
      )}

      {dialog?.type === 'disable' && (
        <DisableServiceDialog
          project={dialog.project}
          service={dialog.service}
          onCancel={close}
          onConfirm={() => run((revision) => client.disableService(workspace.id, dialog.project.id, dialog.service, revision), { success: `${serviceName(dialog.service)} is off for ${dialog.project.name}.` })}
          onDone={close}
        />
      )}

      {dialog?.type === 'delete' && (
        <ProjectDeleteDialog
          project={dialog.project}
          onCancel={close}
          onConfirm={() => run((revision) => client.deleteProject(workspace.id, dialog.project.id, revision), { success: `Deleted ${dialog.project.name}.` })}
          onDone={close}
        />
      )}
    </Card>
  );
}

function ProjectRow({ project, workspaceId, canManage, onService, onRename, onDelete }) {
  const [busyService, setBusyService] = useState('');
  const [error, setError] = useState('');
  const on = (service) => project.services.includes(service);

  const change = async (service, turnOn) => {
    setBusyService(service); setError('');
    const result = await onService(project, service, turnOn);
    setBusyService('');
    if (!result.ok) setError(result.message);
  };

  return (
    <li className="cs-row cs-row--wrap">
      <div className="cs-row__main"><h3 translate="no">{project.name}</h3></div>
      <ul className="cs-services cs-list" aria-label={`Services in ${project.name}`}>
        {SERVICES.map((service) => (
          <li key={service.id} className={`cs-service${on(service.id) ? ' is-on' : ''}`}>
            {on(service.id) && service.open ? (
              <Link className="cs-service__name" to={service.open(workspaceId, project.id)} title={service.description}>
                <span className="sr-only">Open </span>{service.name}<span className="sr-only"> for {project.name}</span><FiArrowUpRight aria-hidden="true" />
              </Link>
            ) : (
              <span className="cs-service__name" title={service.description}>{service.name}{!canManage && <span className="sr-only"> is off</span>}</span>
            )}
            {canManage && (
              <button
                type="button"
                role="switch"
                className="cs-switch"
                aria-checked={on(service.id)}
                aria-label={`${service.name} for ${project.name}`}
                title={on(service.id) ? `Turn off ${service.name}` : `Turn on ${service.name}`}
                disabled={Boolean(busyService)}
                aria-busy={busyService === service.id}
                onClick={() => change(service.id, !on(service.id))}
              ><i aria-hidden="true" /></button>
            )}
          </li>
        ))}
      </ul>
      {canManage && (
        <RowMenu label={`More actions for ${project.name}`}>
          {(close) => (
            <>
              <button type="button" role="menuitem" onClick={() => { close(); onRename(); }}>Rename</button>
              <button type="button" role="menuitem" className="is-danger" onClick={() => { close(); onDelete(); }}>Delete</button>
            </>
          )}
        </RowMenu>
      )}
      {error && <p className="cs-row__error" role="alert">{error}</p>}
    </li>
  );
}

// Both confirmations run their request, show a failure inside the dialog and close on success.
function useConfirm(onConfirm, onDone) {
  const [state, setState] = useState({ busy: false, error: '' });
  const confirm = async () => {
    setState({ busy: true, error: '' });
    const result = await onConfirm();
    if (result.ok) onDone(); else setState({ busy: false, error: result.message });
  };
  return [state, confirm];
}

function DisableServiceDialog({ project, service, onConfirm, onCancel, onDone }) {
  const [{ busy, error }, confirm] = useConfirm(onConfirm, onDone);
  const name = serviceName(service);
  return (
    <ConfirmDialog
      title={`Turn off ${name} for ${project.name}?`}
      confirmLabel={`Turn off ${name}`}
      busyLabel="Turning off…"
      danger
      busy={busy}
      error={error}
      onConfirm={confirm}
      onCancel={onCancel}
    >
      <p>Everyone in this workspace loses access to {name} in this project, and connected apps stop working with it. This takes effect within moments.</p>
      <p>Nothing is deleted. You can turn {name} on again later.</p>
    </ConfirmDialog>
  );
}

function ProjectDeleteDialog({ project, onConfirm, onCancel, onDone }) {
  const [{ busy, error }, confirm] = useConfirm(onConfirm, onDone);
  return (
    <ConfirmDialog
      title={`Delete ${project.name}?`}
      confirmLabel="Delete project"
      busyLabel="Deleting…"
      danger
      busy={busy}
      error={error}
      onConfirm={confirm}
      onCancel={onCancel}
    >
      <p>Everyone loses access to this project and its services, and connected apps stop working with it. This cannot be undone.</p>
    </ConfirmDialog>
  );
}
